CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER) IS
  v_total NUMBER := 0;
  v_max   NUMBER;
BEGIN
  FOR r IN (
    SELECT "No" no,
           "Grape" grape,
           "Winery" winery,
           "Cases" cases,
           "Score" score,
           "Price" price
    FROM "wine"
    WHERE "Score" >= arg1
    ORDER BY "No"
  ) LOOP
    v_total := v_total + r.price;

    IF instr(r.grape, 'prefix_') = 1 THEN
      UPDATE "wine"
      SET "Price" = arg3
      WHERE "No" = r.no;
    ELSIF r.no < arg4 THEN
      DELETE FROM "wine"
      WHERE "No" = r.no;
    ELSIF r.winery = 'Twomey' THEN
      UPDATE "wine"
      SET "Price" = arg3 + r.price
      WHERE "No" = r.no;
    ELSIF r.cases > r.score THEN
      UPDATE "wine"
      SET "Price" = arg3 + r.price
      WHERE "No" = r.no;
    ELSE
      UPDATE "wine"
      SET "Price" = 3 * arg3
      WHERE "No" = r.no;
    END IF;
  END LOOP;

  SELECT MAX("No")
  INTO v_max
  FROM "wine";

  IF v_max IS NULL THEN
    v_max := 1;
  ELSE
    v_max := v_max + 1;
  END IF;

  INSERT INTO "wine" ("No", "Grape", "Price", "Score")
  VALUES (v_max,
          'prefix_' || arg2,
          CASE WHEN v_total > arg4 THEN arg3 + 1 ELSE arg3 END,
          arg1 + 1);
END sp;

